      zj_bt: "2\u4eba\u73a9\u6cd5,\u5f00\u5c40\u5148\u53eb\u5305:\u9009\u62e9\u65e0\u8d22/\u72ec\u8d22/\u53cc\u8d22\u5e76\u62a5\u51fa\u5305\u51e0\u53f0,\u53eb\u53f0\u5927\u7684\u4e00\u65b9\u6210\u4e3a\u5305\u5bb6,\u7531\u5305\u5bb6\u4ece\u624b\u724c\u4e2d\u5b9a\u8d22\u795e\u3002\n\xb7 \u5305\u5bb6\u80e1\u724c\u5fc5\u987b\u8fbe\u5230\u81ea\u5df1\u6240\u5305\u7684\u53f0\u6570,\u95f2\u5bb6\u80e1\u724c\u53ea\u9700\u8fbe\u5230\u6700\u4f4e\u8d77\u80e1\u53f0\u6570\u3002\n\xb7 \u540c\u53f0\u6570\u65f6\u5927\u5c0f\u987a\u5e8f:\u65e0\u8d22 > \u72ec\u8d22 > \u53cc\u8d22\u3002\n\xb7 \u7ed3\u7b97\u5206\u4e24\u9879:\u80e1\u724c\u5206\u6309\u53f0\u6570\u6bcf\u53f0\u7ffb\u500d,\u5305\u53f0\u5206\u6309\u6240\u5305\u53f0\u6570\u6bcf\u53f0\u7ffb\u500d\u3002\n\xb7 \u8001\u5e84\u65f6\u5305\u53f0\u5206\u7ffb\u500d\u3002\n\xb7 \u5305\u5bb6\u4e0d\u5305\u5219\u63a8\u7ed9\u95f2\u5bb6,\u95f2\u5bb6\u4e5f\u4e0d\u5305\u65f6\u7531\u5e84\u5bb6\u6309\u6240\u5305\u53f0\u6570\u786c\u5305\u3002",
      zj_lao: "2\u4eba\u63a8\u5012\u80e1\u73a9\u6cd5,\u6ca1\u6709\u53f0\u6570\u95e8\u69db,\u80e1\u724c\u5373\u7b97\u3002\n\xb7 \u4e0d\u505a\u53f0\u6570\u7ed3\u7b97,\u53ea\u6709\u7ffb\u500d\u9879(\u8d22\u540a\u3001\u5929\u80e1\u3001\u5730\u80e1\u7b49)\u53c2\u4e0e\u8ba1\u5206\u3002\n\xb7 \u5403\u3001\u78b0\u3001\u6760\u3001\u70b9\u70ae\u7b49\u89c4\u5219\u4e0e\u8bf8\u66a8\u9ebb\u5c06\u4e00\u81f4\u3002",
      zj_zx: "2\u4eba\u73a9\u6cd5,\u5f00\u5c40\u4e0d\u53d1\u8d22\u795e\u3002\n\xb7 \u80e1\u724c\u65f6\u81ea\u9009\u8d22\u795e\u65b9\u6848:\u65e0\u8d22\u3001\u72ec\u8d22\u6216\u53cc\u8d22(\u53cc\u8d22\u4e3a\u76f8\u8fde\u7684\u4e24\u5f20)\u3002\n\xb7 \u9009\u5b9a\u65b9\u6848\u540e\u4ece\u624b\u724c\u4e2d\u9009\u51fa\u5bf9\u5e94\u7684\u8d22\u795e\u724c,\u5b9a\u8d22\u795e\u540e\u5373\u6ee1\u8db3\u80e1\u724c\u6761\u4ef6\u3002\n\xb7 \u4ecd\u9700\u8fbe\u5230\u8d77\u80e1\u53f0\u6570\u624d\u80fd\u80e1\u3002\n\xb7 \u65e0\u8d22\u3001\u72ec\u8d22\u65b9\u6848\u8ba1\u5206\u7ffb\u500d\u3002",
      zj4_zx: "4\u4eba\u73a9\u6cd5,\u89c4\u5219\u4e0e2\u4eba\u81ea\u9009\u9ebb\u5c06\u4e00\u81f4,\u5f00\u5c40\u4e0d\u53d1\u8d22\u795e,\u80e1\u724c\u65f6\u81ea\u9009\u8d22\u795e\u65b9\u6848\u3002",
      guanpai2: "2\u4eba\u6251\u514b\u73a9\u6cd5,\u5148\u51fa\u5b8c\u624b\u724c\u7684\u4e00\u65b9\u83b7\u80dc\u3002\n\xb7 \u724c\u578b:\u5355\u5f20\u3001\u5bf9\u5b50\u3001\u4e09\u5f20\u3001\u987a\u5b50\u3001\u70b8\u5f39\u3002\n\xb7 2 \u4e0d\u53c2\u4e0e\u987a\u5b50;A \u53ef\u4f5c\u6700\u5c0f\u724c\u4e0e 2 \u76f8\u8fde\u3002\n\xb7 \u9996\u5c40\u7531\u6301\u6709\u6700\u5c0f\u9ed1\u6843\u7684\u4e00\u65b9\u5148\u51fa,\u4e4b\u540e\u7531\u4e0a\u4e00\u5c40\u8d62\u5bb6\u5148\u51fa\u3002\n\xb7 \u8bb0\u724c\u5668(\u5386\u53f2\u51fa\u724c\u8f85\u52a9)\u3002",
      guanpai3: "3\u4eba\u6251\u514b\u73a9\u6cd5,\u5148\u51fa\u5b8c\u624b\u724c\u7684\u4e00\u65b9\u83b7\u80dc,\u89c4\u5219\u4e0e2\u4eba\u5173\u724c\u4e00\u81f4\u3002",
      sss2: "\u5341\u4e09\u6c34(2\u4eba)\u300252\u5f20\u724c\u6bcf\u4eba\u53d113\u5f20,\u6446\u6210\u59343/\u4e2d5/\u5c3e5\u4e09\u9053\u540e\u4e0e\u5bf9\u624b\u9010\u9053\u6bd4\u724c\u3002\n\xb7 \u724c\u578b\u4ece\u5927\u5230\u5c0f:\u540c\u82b1\u987a > \u94c1\u652f > \u846b\u82a6 > \u540c\u82b1 > \u987a\u5b50 > \u4e09\u6761 > \u4e24\u5bf9 > \u5bf9\u5b50 > \u5355\u5f20\u3002\n\xb7 \u5fc5\u987b\u5934\u9053\u2264\u4e2d\u9053\u2264\u5c3e\u9053,\u987a\u5e8f\u4e0d\u7b26\u4e0d\u5141\u8bb8\u63d0\u4ea4\u3002\n\xb7 \u6bcf\u8d62\u4e00\u9053+1\u6ce8;\u4e09\u9053\u5168\u80dc\u6253\u67aa\u518d+3\u6ce8\u3002\n\xb7 \u7279\u6b8a\u724c\u578b\u901a\u5403:\u4e00\u6761\u9f99\xd73\u3001\u516d\u5bf9\u534a\xd74\u3001\u4e09\u540c\u82b1/\u4e09\u987a\u5b50\xd75\u3001\u4e09\u5206\u5929\u4e0b\xd76\u3002\n\xb7 \u6446\u724c\u9650\u65f6,\u8d85\u65f6\u7cfb\u7edf\u81ea\u52a8\u6446\u724c;\u4e5f\u53ef\u70b9\u300c\u81ea\u52a8\u6446\u724c\u300d\u3002",
      sss4: "\u5341\u4e09\u6c34(4\u4eba)\u3002\u89c4\u5219\u4e0e2\u4eba\u5341\u4e09\u6c34\u4e00\u81f4,\u6bcf\u4eba13\u5f20,\u4e0e\u5176\u4f593\u5bb6\u9010\u9053\u6bd4\u724c\u3002\n\xb7 \u724c\u578b\u4ece\u5927\u5230\u5c0f:\u540c\u82b1\u987a > \u94c1\u652f > \u846b\u82a6 > \u540c\u82b1 > \u987a\u5b50 > \u4e09\u6761 > \u4e24\u5bf9 > \u5bf9\u5b50 > \u5355\u5f20\u3002\n\xb7 \u5fc5\u987b\u5934\u9053\u2264\u4e2d\u9053\u2264\u5c3e\u9053,\u987a\u5e8f\u4e0d\u7b26\u4e0d\u5141\u8bb8\u63d0\u4ea4\u3002\n\xb7 \u6bcf\u8d62\u4e00\u9053+1\u6ce8;\u4e09\u9053\u5168\u80dc\u6253\u67aa\u518d+3\u6ce8;\u8d62\u8fc7\u5168\u90e8\u5bf9\u624b\u4e3a\u5168\u5792\u6253,\u6bcf\u5bb6\u518d+3\u6ce8\u3002\n\xb7 \u7279\u6b8a\u724c\u578b\u901a\u5403:\u4e00\u6761\u9f99\xd73\u3001\u516d\u5bf9\u534a\xd74\u3001\u4e09\u540c\u82b1/\u4e09\u987a\u5b50\xd75\u3001\u4e09\u5206\u5929\u4e0b\xd76\u3002\n\xb7 \u6446\u724c\u9650\u65f6,\u8d85\u65f6\u7cfb\u7edf\u81ea\u52a8\u6446\u724c;\u4e5f\u53ef\u70b9\u300c\u81ea\u52a8\u6446\u724c\u300d\u3002",
