            nc.setPosition(start);
            nc.opacity = 0;
            nc.runAction(cc.sequence(cc.delayTime(i * STEP), cc.spawn(cc.moveTo(FLY, cc.v2(fx, fy)), cc.fadeTo(FLY, fop))));
            var end = i * STEP + FLY;
