          "play_hu" == name ? spKey = "mj_hu" : "play_zimo" == name ? spKey = "mj_zimo" : "play_chi" == name ? spKey = "mj_chi" : "play_peng" == name ? spKey = "mj_peng" : "play_guafeng" != name && "play_xiayu" != name && "play_gang" != name || (spKey = "mj_gang");
          spKey && cc.vv.mahjongmgr.playSpineEfx(efxNode, spKey);
