        var cfg = this._dlgCfg;
        var titlePrefix = this._dlgTable ? "\u4fee\u6539\u724c\u684c" : isEdit ? "\u4fee\u6539\u73a9\u6cd5" : "\u65b0\u5efa\u73a9\u6cd5";
