        var isBaobao = /^baobao/.test(this._dlgGameType);
        var ruleRows = [ "shuffle_score", "rake_percent", "hidden_rake_percent", "room_fee" ];
        for (var i = 0; i < ruleRows.length; i++) this._setRuleRow(content, ruleRows[i], true, unified);
