        for (var hi = 0; hi < hideFeeRate.length; hi++) {
          var hNode = content.getChildByName(hideFeeRate[hi]);
          if (hNode) {
            hNode.active = true;
            hNode.opacity = 120;
            var hEb = hNode.getComponent(cc.EditBox);
            hEb && ("boolean" === typeof hEb.interactable ? hEb.interactable = false : hEb.enabled = false);
          }
        }
